package com.ella.grounditemscolourgroups;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * One of a colour group's wildcard patterns, how many items in the game currently match it, and
 * one sample match's icon (the first one found, alphabetically) to give the row a recognisable
 * face instead of a blank placeholder - null if nothing currently matches. Shown as a single
 * summary row in the panel rather than expanding out every matching item. Value-based
 * equals/hashCode so the panel can tell whether a freshly rebuilt one is identical to the last one
 * it rendered, and skip re-rendering if so.
 */
@Getter
@EqualsAndHashCode
class PatternMatch
{
	private final String pattern;
	private final int matchCount;
	private final AsyncBufferedImage sampleImage;

	PatternMatch(String pattern, int matchCount, AsyncBufferedImage sampleImage)
	{
		this.pattern = pattern;
		this.matchCount = matchCount;
		this.sampleImage = sampleImage;
	}
}

package com.ella.grounditemscolourgroups;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.ui.PluginPanel;

class GroundItemColourGroupsPanel extends PluginPanel
{
	private final PanelCallbacks callbacks;
	private final JPanel groupsContainer = new JPanel();

	/**
	 * Colours whose group is currently collapsed - purely a display preference, so it's kept here
	 * rather than round-tripped through the plugin/config, and toggling it just re-renders the last
	 * groups the plugin gave us instead of asking for a fresh refresh.
	 */
	private final Set<Color> collapsedGroups = new HashSet<>();
	private List<ColourGroup> lastGroups = Collections.emptyList();

	/**
	 * The group and collapsed state each colour's currently-displayed JPanel was last built from,
	 * so a refresh can tell whether a colour actually changed since last time and, if not, reuse its
	 * existing row components instead of tearing down and rebuilding them - the difference between a
	 * group of a couple of items and one of several hundred otherwise redoing the same, potentially
	 * very expensive, Swing construction on every single refresh, no matter which group it was that
	 * actually changed.
	 */
	private final Map<Color, ColourGroup> renderedGroupByColour = new HashMap<>();
	private final Map<Color, Boolean> renderedCollapsedByColour = new HashMap<>();
	private final Map<Color, JPanel> renderedPanelByColour = new HashMap<>();

	GroundItemColourGroupsPanel(PanelCallbacks callbacks)
	{
		super();
		this.callbacks = callbacks;

		JLabel title = new JLabel("Ground Item Colour Groups");
		title.setForeground(Color.WHITE);
		title.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);

		JButton addButton = new JButton("+ Add");
		addButton.setToolTipText("Assign a new item to a colour");
		addButton.addActionListener(e -> callbacks.addNewGroup());

		JButton addPatternButton = new JButton("+ Pattern");
		addPatternButton.setToolTipText("<html><body style='width:220px'>Start a new colour group from a wildcard "
			+ "name pattern (e.g. \"Clue scroll*\") instead of one item at a time - handy for large families like "
			+ "clue rewards.</body></html>");
		addPatternButton.addActionListener(e -> callbacks.addPatternGroup());

		// A single refresh action, always a full one: wipes this plugin's cached item names/icons
		// and its wildcard item index before rebuilding, so there's no separate "lightweight" mode
		// that could still be stuck showing "Item <number>" or a pattern stuck at 0 matches (both of
		// which can happen if the game's item cache wasn't ready yet the moment the panel first
		// loaded). A compact icon rather than a text button so it fits on one row alongside the
		// other two - the panel is a fixed 225px-wide sidebar (PluginPanel.PANEL_WIDTH).
		JButton refreshButton = new JButton("↻");
		refreshButton.setToolTipText("<html><body style='width:220px'>Refresh: re-scans everything, wiping this "
			+ "plugin's cached item names/icons and wildcard item index first so it's always a full "
			+ "rebuild.</body></html>");
		refreshButton.setMargin(new java.awt.Insets(0, 6, 0, 6));
		refreshButton.addActionListener(e -> callbacks.forceRefresh());

		JPanel headerButtons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		headerButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		headerButtons.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
		headerButtons.add(addButton);
		headerButtons.add(addPatternButton);
		headerButtons.add(refreshButton);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.add(title);
		header.add(Box.createVerticalStrut(4));
		header.add(headerButtons);

		groupsContainer.setLayout(new BoxLayout(groupsContainer, BoxLayout.Y_AXIS));
		groupsContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(header);
		add(groupsContainer);

		showEmptyMessage();
	}

	void showGroups(List<ColourGroup> groups)
	{
		lastGroups = groups;
		renderGroups();
	}

	/**
	 * Rebuilds the group list from {@code lastGroups} without asking the plugin to recompute
	 * anything - used both when the plugin hands us a fresh list and when a purely local display
	 * change (collapsing a group) needs to be reflected immediately.
	 */
	private void renderGroups()
	{
		groupsContainer.removeAll();

		if (lastGroups.isEmpty())
		{
			showEmptyMessage();
		}
		else
		{
			Set<Color> stillPresent = new HashSet<>();
			for (ColourGroup group : lastGroups)
			{
				Color colour = group.getColour();
				stillPresent.add(colour);
				boolean collapsed = collapsedGroups.contains(colour);

				JPanel groupPanel;
				if (group.equals(renderedGroupByColour.get(colour))
					&& Boolean.valueOf(collapsed).equals(renderedCollapsedByColour.get(colour)))
				{
					// Nothing about this colour changed since it was last built - reuse its rows
					// rather than redoing potentially hundreds of them for no reason.
					groupPanel = renderedPanelByColour.get(colour);
				}
				else
				{
					groupPanel = buildGroupPanel(group, collapsed);
					renderedGroupByColour.put(colour, group);
					renderedCollapsedByColour.put(colour, collapsed);
					renderedPanelByColour.put(colour, groupPanel);
				}

				groupsContainer.add(groupPanel);
				groupsContainer.add(Box.createVerticalStrut(6));
			}

			renderedGroupByColour.keySet().retainAll(stillPresent);
			renderedCollapsedByColour.keySet().retainAll(stillPresent);
			renderedPanelByColour.keySet().retainAll(stillPresent);
		}

		groupsContainer.revalidate();
		groupsContainer.repaint();
	}

	private void showEmptyMessage()
	{
		JLabel empty = new JLabel("<html><body style='width: 180px'>No items have a custom Ground Items colour "
			+ "yet. Click \"+ Add\" to pick one item, \"+ Pattern\" to match many by name (e.g. clue rewards), or "
			+ "right-click an item on the ground and use the Ground Items highlight option - it will show up "
			+ "here.</body></html>");
		empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		groupsContainer.add(empty);
	}

	private JPanel buildGroupPanel(ColourGroup group, boolean collapsed)
	{
		Color colour = group.getColour();
		List<ColouredGroundItem> items = group.getItems();
		List<PatternMatch> patternMatches = group.getPatternMatches();
		boolean enabled = group.isEnabled();

		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createLineBorder(enabled ? colour : ColorScheme.MEDIUM_GRAY_COLOR, 2));

		JLabel swatchLabel = new JLabel(group.getName() + (enabled ? "" : " — off"));
		swatchLabel.setOpaque(true);
		swatchLabel.setBackground(colour);
		swatchLabel.setForeground(readableTextColour(colour));
		swatchLabel.setHorizontalAlignment(SwingConstants.CENTER);
		swatchLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		swatchLabel.setToolTipText("Click to rename this colour group");
		swatchLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				callbacks.renameGroup(colour);
			}
		});

		JButton collapseButton = new JButton(collapsed ? "▶" : "▼");
		collapseButton.setToolTipText(collapsed ? "Expand this colour group" : "Collapse this colour group");
		collapseButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		collapseButton.addActionListener(e ->
		{
			if (collapsed)
			{
				collapsedGroups.remove(colour);
			}
			else
			{
				collapsedGroups.add(colour);
			}
			renderGroups();
		});

		JCheckBox enabledCheckbox = new JCheckBox();
		enabledCheckbox.setSelected(enabled);
		enabledCheckbox.setOpaque(false);
		enabledCheckbox.setToolTipText(enabled
			? "Turn off this colour group (removes the highlight from every item in it, but remembers the colour "
				+ "and pauses any wildcard patterns)"
			: "Turn this colour group back on (restores the highlight for every item in it, and resumes any "
				+ "wildcard patterns)");
		enabledCheckbox.addActionListener(e -> callbacks.setGroupEnabled(colour, enabledCheckbox.isSelected()));

		JPanel swatchLeft = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
		swatchLeft.setBackground(colour);
		swatchLeft.add(collapseButton);
		swatchLeft.add(enabledCheckbox);

		JButton addToGroupButton = new JButton("+");
		addToGroupButton.setToolTipText("Add another item to this colour");
		addToGroupButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		addToGroupButton.addActionListener(e -> callbacks.addToGroup(colour));

		List<String> patterns = new ArrayList<>();
		for (PatternMatch patternMatch : patternMatches)
		{
			patterns.add(patternMatch.getPattern());
		}

		JButton patternsButton = new JButton("*");
		patternsButton.setToolTipText(patterns.isEmpty()
			? "Add a wildcard name pattern (e.g. \"Clue scroll*\") so matching items join this colour automatically"
			: "<html><body style='width:220px'>Add another wildcard pattern to this colour (already has: "
				+ String.join(", ", patterns) + ")</body></html>");
		patternsButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		patternsButton.addActionListener(e -> callbacks.addPattern(colour));

		JButton deleteButton = new JButton("Delete");
		deleteButton.setToolTipText("Delete this whole colour group: every item's highlight and every wildcard "
			+ "pattern in it");
		deleteButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		deleteButton.addActionListener(e -> callbacks.deleteGroup(colour));

		JPanel swatchButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		swatchButtons.setBackground(colour);
		swatchButtons.add(patternsButton);
		swatchButtons.add(addToGroupButton);
		swatchButtons.add(deleteButton);

		JPanel swatchRow = new JPanel(new BorderLayout());
		swatchRow.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		swatchRow.setBackground(colour);
		swatchRow.add(swatchLeft, BorderLayout.WEST);
		swatchRow.add(swatchLabel, BorderLayout.CENTER);
		swatchRow.add(swatchButtons, BorderLayout.EAST);
		panel.add(swatchRow);

		if (!collapsed)
		{
			for (PatternMatch patternMatch : patternMatches)
			{
				panel.add(buildPatternRow(colour, patternMatch));
			}

			for (ColouredGroundItem item : items)
			{
				panel.add(buildItemRow(colour, item));
			}
		}

		return panel;
	}

	/**
	 * One row per wildcard pattern - not one per matching item, however many there are - showing
	 * the pattern text itself and a live count of how many items currently match it.
	 */
	private JPanel buildPatternRow(Color groupColour, PatternMatch patternMatch)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));

		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(20, 20));
		iconLabel.setOpaque(true);
		iconLabel.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		iconLabel.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
		if (patternMatch.getSampleImage() != null)
		{
			// Still keeps the box background/border above - just gives it a real face (the first
			// current match, alphabetically) instead of leaving it blank when there's one to show.
			setScaledIcon(iconLabel, patternMatch.getSampleImage());
		}

		JLabel nameLabel = new JLabel(String.format("%s  (%d item%s)", patternMatch.getPattern(),
			patternMatch.getMatchCount(), patternMatch.getMatchCount() == 1 ? "" : "s"));
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setToolTipText("<html><body style='width:220px'>Wildcard pattern - every item whose name matches "
			+ "this gets this group's colour automatically, including items added to the game later.</body></html>");

		JButton recolourButton = new JButton();
		recolourButton.setToolTipText("Move this pattern (and its matches) to a different colour group");
		recolourButton.setBackground(groupColour);
		recolourButton.setPreferredSize(new Dimension(16, 16));
		recolourButton.addActionListener(e -> callbacks.changePatternColour(groupColour, patternMatch.getPattern()));

		JButton removeButton = new JButton("×");
		removeButton.setToolTipText("Remove this wildcard pattern");
		removeButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		removeButton.addActionListener(e -> callbacks.removePattern(groupColour, patternMatch.getPattern()));

		JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.add(recolourButton);
		actions.add(removeButton);

		row.add(iconLabel, BorderLayout.WEST);
		row.add(nameLabel, BorderLayout.CENTER);
		row.add(actions, BorderLayout.EAST);

		return row;
	}

	private JPanel buildItemRow(Color groupColour, ColouredGroundItem item)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));

		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(20, 20));
		setScaledIcon(iconLabel, item.getImage());

		JLabel nameLabel = new JLabel(item.getName());
		nameLabel.setForeground(Color.WHITE);

		JButton recolourButton = new JButton();
		recolourButton.setToolTipText("Change this item's colour");
		recolourButton.setBackground(groupColour);
		recolourButton.setPreferredSize(new Dimension(16, 16));
		recolourButton.addActionListener(e -> callbacks.changeItemColour(item.getItemId(), groupColour));

		JButton removeButton = new JButton("×");
		removeButton.setToolTipText("Remove this item's custom colour");
		removeButton.setMargin(new java.awt.Insets(0, 4, 0, 4));
		removeButton.addActionListener(e -> callbacks.removeItem(item.getItemId()));

		JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.add(recolourButton);
		actions.add(removeButton);

		row.add(iconLabel, BorderLayout.WEST);
		row.add(nameLabel, BorderLayout.CENTER);
		row.add(actions, BorderLayout.EAST);

		return row;
	}

	private static Color readableTextColour(Color background)
	{
		double luminance = (0.299 * background.getRed() + 0.587 * background.getGreen() + 0.114 * background.getBlue()) / 255;
		return luminance > 0.55 ? Color.BLACK : Color.WHITE;
	}

	private static final int ICON_BOX_SIZE = 20;
	private static final double ICON_SCALE = 0.7;

	/**
	 * Shows {@code image} shrunk to {@link #ICON_SCALE} of its natural size and centred in a
	 * {@link #ICON_BOX_SIZE}-square box, repainting once the async image actually finishes loading -
	 * the same "notify when ready" behaviour {@link AsyncBufferedImage#addTo} provides, just with
	 * scaling applied instead of drawing at full (often oversized) native resolution.
	 */
	private static void setScaledIcon(JLabel label, AsyncBufferedImage image)
	{
		label.setIcon(new ScaledIcon(image, ICON_BOX_SIZE, ICON_SCALE));
		image.onLoaded(label::repaint);
	}
}

package com.ella.grounditemscolourgroups;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Window;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.grounditems.GroundItemsConfig;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;
import net.runelite.client.util.AsyncBufferedImage;

@Slf4j
@PluginDescriptor(
	name = "Ground Item Colour Groups",
	description = "Adds a side panel listing every item you've given a custom colour in the Ground Items "
		+ "plugin, grouped by that colour, and lets you add, recolour or remove entries from the panel",
	tags = { "ground", "items", "colour", "color", "highlight", "panel", "grounditems" }
)
public class GroundItemColourGroupsPlugin extends Plugin implements PanelCallbacks
{
	/**
	 * Mirrors the private HIGHLIGHT_COLOR_PREFIX constant in the built-in GroundItemsPlugin, which stores each
	 * manually-coloured item's colour under the config key "highlight_" + itemId within GroundItemsConfig.GROUP.
	 * That constant isn't public, so it's duplicated here rather than depended on.
	 */
	private static final String HIGHLIGHT_KEY_PREFIX = "highlight_";

	/**
	 * This plugin's own config group, used for state the built-in Ground Items plugin has no notion
	 * of: remembering the colour of bulk-disabled, individually-added items (DISABLED_KEY_PREFIX +
	 * itemId), which whole colour groups are currently toggled off (DISABLED_GROUPS_KEY), each
	 * colour's wildcard name patterns (PATTERN_KEY_PREFIX + colour hex), and each colour's custom
	 * display name (NAME_KEY_PREFIX + colour hex).
	 */
	private static final String OWN_CONFIG_GROUP = "grounditemcolourgroups";
	private static final String DISABLED_KEY_PREFIX = "disabled_";
	private static final String DISABLED_GROUPS_KEY = "disabledGroupColours";
	private static final String PATTERN_KEY_PREFIX = "patterns_";
	private static final String NAME_KEY_PREFIX = "name_";

	@Inject
	private ConfigManager configManager;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ColorPickerManager colourPickerManager;

	private GroundItemColourGroupsPanel panel;
	private NavigationButton navButton;

	/**
	 * Every item known to the client, tradeable or not, keyed by its canonical (un-noted,
	 * un-placeholdered) id. Built lazily on first use since it requires a full scan of the item
	 * cache on the client thread; the result doesn't change during a session so it's cached here.
	 * Volatile since it's written on the client thread and read on the EDT.
	 */
	private volatile List<SearchItem> itemIndex;

	/**
	 * Set for the duration of a bulk config write (moving a whole group between enabled/disabled,
	 * or auto-applying a wildcard pattern to newly-matching items) so the resulting flood of
	 * ConfigChanged events - one per item - doesn't each trigger their own full panel refresh. The
	 * caller of the bulk write still triggers exactly one refresh() itself once it's done.
	 */
	private volatile boolean suppressConfigEvents;

	/**
	 * Compiled form of every wildcard pattern seen so far, keyed by the raw pattern text.
	 * {@link net.runelite.client.util.WildcardMatcher#matches} recompiles a fresh {@link Pattern}
	 * from scratch on every single call (it ultimately calls {@link String#matches}, which never
	 * caches) - fine for checking one string once, but ruinous when matching the same handful of
	 * patterns against every item in the client's ~20-30k item catalogue on every refresh, which is
	 * exactly what pattern matching/counting does. Compiling each pattern once here and reusing the
	 * compiled Pattern (a cheap Matcher per item, no recompilation) is what makes that affordable.
	 * Only ever touched from the client thread, so a plain HashMap is fine.
	 */
	private final Map<String, Pattern> wildcardPatternCache = new HashMap<>();

	/**
	 * An item's name and icon never change, so once resolved for an id it's kept here rather than
	 * re-fetched on every refresh. Without this, having, say, 400 items in one colour meant every
	 * single refresh - triggered by altering ANY group, not just that one - redid all 400
	 * itemManager lookups and, more importantly (see ColourGroup/PatternMatch's equals()), produced
	 * 400 brand new item objects that could never compare equal to the previous refresh's, forcing
	 * the panel to rebuild that whole group's rows every time regardless of what actually changed.
	 * Only ever touched from the client thread, so a plain HashMap is fine.
	 */
	private final Map<Integer, ColouredGroundItem> hydrationCache = new HashMap<>();

	@Override
	protected void startUp()
	{
		panel = new GroundItemColourGroupsPanel(this);

		navButton = NavigationButton.builder()
			.tooltip("Ground Item Colour Groups")
			.icon(createIcon())
			.priority(9)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		refresh();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (suppressConfigEvents)
		{
			return;
		}

		// Only react to our own highlight_ keys changing (e.g. via the game's right-click Ground
		// Items menu) - not every other, unrelated Ground Items setting, which would otherwise
		// force a full rebuild (including refetching every displayed item's name/icon) on every
		// keystroke in that plugin's config panel.
		if (GroundItemsConfig.GROUP.equals(event.getGroup()) && event.getKey() != null
			&& event.getKey().startsWith(HIGHLIGHT_KEY_PREFIX))
		{
			refresh();
		}
	}

	private void refresh()
	{
		clientThread.invoke(() ->
		{
			List<ColourGroup> groups = buildGroups();
			SwingUtilities.invokeLater(() -> panel.showGroups(groups));
		});
	}

	@Override
	public void forceRefresh()
	{
		clientThread.invoke(() ->
		{
			// The escape hatch for exactly the kind of stuck state a bad item-cache timing (e.g.
			// right after a game update) can cause: wipes every cache this plugin keeps so
			// everything - names, icons, the wildcard item index - gets looked up fresh, rather
			// than only self-healing the specific entries a normal refresh happens to touch.
			hydrationCache.clear();
			wildcardPatternCache.clear();
			itemIndex = null;
			refresh();
		});
	}

	@Override
	public void addNewGroup()
	{
		RuneliteColorPicker picker = colourPickerManager.create(panel, Color.WHITE, "New colour group", false);
		picker.setOnClose(colour ->
		{
			if (colour != null)
			{
				openItemSearch(colour);
			}
		});
		picker.setVisible(true);
	}

	@Override
	public void addToGroup(Color groupColour)
	{
		openItemSearch(groupColour);
	}

	@Override
	public void addPatternGroup()
	{
		RuneliteColorPicker picker = colourPickerManager.create(panel, Color.WHITE, "New colour group", false);
		picker.setOnClose(colour ->
		{
			if (colour != null)
			{
				addPattern(colour);
			}
		});
		picker.setVisible(true);
	}

	@Override
	public void addPattern(Color groupColour)
	{
		Object input = JOptionPane.showInputDialog(panel,
			"<html><body style='width:240px'>New wildcard pattern (* matches anything), matched case-insensitively "
				+ "against item names - e.g. \"Clue scroll*\". Matching items get this colour automatically, "
				+ "including items added to the game later.</body></html>",
			"Add wildcard pattern", JOptionPane.PLAIN_MESSAGE, null, null, "");

		if (input == null)
		{
			return;
		}

		String pattern = input.toString().trim();
		if (pattern.isEmpty())
		{
			return;
		}

		// Purely additive - always read the current list and add to it, never replace it wholesale,
		// so adding a pattern can never accidentally wipe out ones already there (e.g. from picking
		// the same colour twice, or re-adding after an unrelated group's colour happened to match).
		String hex = colourHex(groupColour);
		List<String> patterns = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex));
		if (!patterns.contains(pattern))
		{
			patterns.add(pattern);
			configManager.setConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex, String.join(", ", patterns));
			refresh();
		}
	}

	@Override
	public void removePattern(Color groupColour, String pattern)
	{
		clientThread.invoke(() ->
		{
			String hex = colourHex(groupColour);
			List<String> remainingPatterns = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex));
			remainingPatterns.remove(pattern);

			applyPatternDiff(groupColour, Collections.singletonList(pattern), remainingPatterns);

			if (remainingPatterns.isEmpty())
			{
				configManager.unsetConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex);
			}
			else
			{
				configManager.setConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex, String.join(", ", remainingPatterns));
			}
			refresh();
		});
	}

	@Override
	public void changePatternColour(Color currentColour, String pattern)
	{
		RuneliteColorPicker picker = colourPickerManager.create(panel, currentColour, "Pattern colour", false);
		picker.setOnClose(newColour ->
		{
			if (newColour != null && !newColour.equals(currentColour))
			{
				movePattern(currentColour, pattern, newColour);
			}
		});
		picker.setVisible(true);
	}

	@Override
	public void renameGroup(Color groupColour)
	{
		String hex = colourHex(groupColour);
		String currentName = configManager.getConfiguration(OWN_CONFIG_GROUP, NAME_KEY_PREFIX + hex);

		Object input = JOptionPane.showInputDialog(panel,
			"Name for this colour group (leave blank to show its colour code instead):",
			"Rename colour group", JOptionPane.PLAIN_MESSAGE, null, null, currentName == null ? "" : currentName);

		if (input != null)
		{
			String trimmed = input.toString().trim();
			if (trimmed.isEmpty())
			{
				configManager.unsetConfiguration(OWN_CONFIG_GROUP, NAME_KEY_PREFIX + hex);
			}
			else
			{
				configManager.setConfiguration(OWN_CONFIG_GROUP, NAME_KEY_PREFIX + hex, trimmed);
			}
			refresh();
		}
	}

	@Override
	public void deleteGroup(Color groupColour)
	{
		// A plain YES_NO showConfirmDialog defaults focus to Yes; built via showOptionDialog instead
		// so "No" is the focused/default button - accidentally hitting enter shouldn't delete a group.
		Object[] options = { "Yes", "No" };
		int confirmed = JOptionPane.showOptionDialog(panel,
			"<html><body style='width:220px'>Delete this whole colour group? This removes every item's highlight "
				+ "and every wildcard pattern in it. This can't be undone.</body></html>",
			"Delete colour group", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);

		if (confirmed != 0)
		{
			return;
		}

		clientThread.invoke(() ->
		{
			String hex = colourHex(groupColour);

			suppressConfigEvents = true;
			try
			{
				unsetAllAtColour(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX, groupColour);
				unsetAllAtColour(OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX, groupColour);
			}
			finally
			{
				suppressConfigEvents = false;
			}

			configManager.unsetConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex);
			configManager.unsetConfiguration(OWN_CONFIG_GROUP, NAME_KEY_PREFIX + hex);
			removeDisabledGroupMarker(groupColour);

			refresh();
		});
	}

	/**
	 * Unsets every {@code keyPrefix + itemId} entry under {@code configGroup} whose stored colour
	 * equals {@code colour} - the "delete everything at this colour" building block shared by
	 * deleteGroup for both the live GroundItemsConfig entries and this plugin's own disabled store.
	 */
	private void unsetAllAtColour(String configGroup, String keyPrefix, Color colour)
	{
		String prefix = configGroup + "." + keyPrefix;
		List<String> keys = configManager.getConfigurationKeys(prefix);

		for (String wholeKey : keys)
		{
			int itemId = parseItemId(wholeKey, prefix);
			if (itemId < 0)
			{
				continue;
			}

			Color itemColour = configManager.getConfiguration(configGroup, keyPrefix + itemId, Color.class);
			if (colour.equals(itemColour))
			{
				configManager.unsetConfiguration(configGroup, keyPrefix + itemId);
			}
		}
	}

	private String groupDisplayName(Color colour)
	{
		String custom = configManager.getConfiguration(OWN_CONFIG_GROUP, NAME_KEY_PREFIX + colourHex(colour));
		if (custom != null && !custom.trim().isEmpty())
		{
			return custom.trim();
		}
		return String.format("#%06X", colour.getRGB() & 0xFFFFFF);
	}

	/**
	 * Moves one pattern from {@code oldColour}'s list to {@code newColour}'s, cleaning up the old
	 * colour's now-orphaned matches the same way removing a pattern does. The matches themselves
	 * pick up {@code newColour} on their own in the very next refresh's pattern reconciliation, since
	 * by then they have no highlight_ entry and the pattern is listed under the new colour.
	 */
	private void movePattern(Color oldColour, String pattern, Color newColour)
	{
		clientThread.invoke(() ->
		{
			String oldHex = colourHex(oldColour);
			List<String> oldColourRemaining = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + oldHex));
			oldColourRemaining.remove(pattern);

			applyPatternDiff(oldColour, Collections.singletonList(pattern), oldColourRemaining);

			if (oldColourRemaining.isEmpty())
			{
				configManager.unsetConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + oldHex);
			}
			else
			{
				configManager.setConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + oldHex, String.join(", ", oldColourRemaining));
			}

			String newHex = colourHex(newColour);
			List<String> newColourPatterns = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + newHex));
			if (!newColourPatterns.contains(pattern))
			{
				newColourPatterns.add(pattern);
			}
			configManager.setConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + newHex, String.join(", ", newColourPatterns));

			refresh();
		});
	}

	/**
	 * Unsets the highlight_ entry for every item that matched one of {@code oldPatterns} but none of
	 * {@code newPatterns}, so removing or narrowing a pattern doesn't leave its former matches with a
	 * highlight_ entry indistinguishable from a manually-added item - it would otherwise keep
	 * showing up, just as its own individually-managed row, forever. Only touches items still
	 * coloured with this exact colour, so a manual recolour since is left alone; a manually-added
	 * item whose name happens to also match the old pattern is still affected here though - storage
	 * can't tell the two apart, the same trade-off already made when patterns skip re-hydrating
	 * matched items.
	 */
	private void applyPatternDiff(Color colour, List<String> oldPatterns, List<String> newPatterns)
	{
		if (oldPatterns.isEmpty())
		{
			return;
		}

		ensureItemIndexBuilt();
		List<SearchItem> index = itemIndex;
		if (index == null)
		{
			return;
		}

		suppressConfigEvents = true;
		try
		{
			for (SearchItem candidate : index)
			{
				if (!matchesAny(candidate.getName(), oldPatterns) || matchesAny(candidate.getName(), newPatterns))
				{
					continue;
				}

				Color current = configManager.getConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + candidate.getId(), Color.class);
				if (colour.equals(current))
				{
					configManager.unsetConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + candidate.getId());
				}
			}
		}
		finally
		{
			suppressConfigEvents = false;
		}
	}

	@Override
	public void removeItem(int itemId)
	{
		// Suppressed and refreshed explicitly rather than left to onConfigChanged: if the item is
		// currently in the disabled store, only OWN_CONFIG_GROUP changes, which that listener
		// doesn't watch, and the panel would never notice the removal.
		suppressConfigEvents = true;
		try
		{
			configManager.unsetConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + itemId);
			configManager.unsetConfiguration(OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX + itemId);
		}
		finally
		{
			suppressConfigEvents = false;
		}
		refresh();
	}

	@Override
	public void changeItemColour(int itemId, Color currentColour)
	{
		RuneliteColorPicker picker = colourPickerManager.create(panel, currentColour, "Item colour", false);
		picker.setOnClose(colour ->
		{
			if (colour != null)
			{
				boolean disabled = configManager.getConfiguration(OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX + itemId, Color.class) != null;
				suppressConfigEvents = true;
				try
				{
					if (disabled)
					{
						configManager.setConfiguration(OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX + itemId, colour);
					}
					else
					{
						configManager.setConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + itemId, colour);
					}
				}
				finally
				{
					suppressConfigEvents = false;
				}
				refresh();
			}
		});
		picker.setVisible(true);
	}

	@Override
	public void setGroupEnabled(Color groupColour, boolean enabled)
	{
		clientThread.invoke(() ->
		{
			if (enabled)
			{
				removeDisabledGroupMarker(groupColour);
				// Every disabled_ entry is manually-added (patterns are never stored there, see
				// disableGroup below), so all of them are restored.
				moveGroup(groupColour, OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX, GroundItemsConfig.GROUP,
					HIGHLIGHT_KEY_PREFIX, Collections.emptySet());
			}
			else
			{
				addDisabledGroupMarker(groupColour);
				disableGroup(groupColour);
			}
			refresh();
		});
	}

	/**
	 * Disabling a colour group has to actually remove every one of its items' highlight_ entries so
	 * the game stops showing them, but only the manually-added ones need remembering in the
	 * disabled_ store to be restored later - a pattern-matched item's colour is just re-derived from
	 * the pattern the next time the group is re-enabled, so it's simply unset here instead of also
	 * being written to the (potentially hundreds-of-keys) disabled_ store.
	 */
	private void disableGroup(Color colour)
	{
		moveGroup(colour, GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX, OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX,
			currentPatternMatchIds(colour));
	}

	/**
	 * Moves every item whose colour under {@code fromGroup}/{@code fromPrefix} equals
	 * {@code colour} over to {@code toGroup}/{@code toPrefix}, except ids in {@code unsetOnly} which
	 * are just unset from {@code fromGroup} without being written anywhere - used to drop
	 * pattern-matched items without spending a config key remembering each one individually. The
	 * whole loop is one suppressed burst so it costs a single refresh, not one per item moved.
	 */
	private void moveGroup(Color colour, String fromGroup, String fromPrefix, String toGroup, String toPrefix,
		Set<Integer> unsetOnly)
	{
		String prefix = fromGroup + "." + fromPrefix;
		List<String> keys = configManager.getConfigurationKeys(prefix);

		suppressConfigEvents = true;
		try
		{
			for (String wholeKey : keys)
			{
				int itemId = parseItemId(wholeKey, prefix);
				if (itemId < 0)
				{
					continue;
				}

				Color itemColour = configManager.getConfiguration(fromGroup, fromPrefix + itemId, Color.class);
				if (itemColour == null || !itemColour.equals(colour))
				{
					continue;
				}

				if (!unsetOnly.contains(itemId))
				{
					configManager.setConfiguration(toGroup, toPrefix + itemId, itemColour);
				}
				configManager.unsetConfiguration(fromGroup, fromPrefix + itemId);
			}
		}
		finally
		{
			suppressConfigEvents = false;
		}
	}

	private Set<String> readDisabledGroupHexes()
	{
		String csv = configManager.getConfiguration(OWN_CONFIG_GROUP, DISABLED_GROUPS_KEY);
		Set<String> hexes = new HashSet<>();
		if (csv != null)
		{
			for (String hex : csv.split(","))
			{
				String trimmed = hex.trim();
				if (!trimmed.isEmpty())
				{
					hexes.add(trimmed);
				}
			}
		}
		return hexes;
	}

	private void addDisabledGroupMarker(Color colour)
	{
		Set<String> hexes = readDisabledGroupHexes();
		if (hexes.add(colourHex(colour)))
		{
			configManager.setConfiguration(OWN_CONFIG_GROUP, DISABLED_GROUPS_KEY, String.join(",", hexes));
		}
	}

	private void removeDisabledGroupMarker(Color colour)
	{
		Set<String> hexes = readDisabledGroupHexes();
		if (hexes.remove(colourHex(colour)))
		{
			if (hexes.isEmpty())
			{
				configManager.unsetConfiguration(OWN_CONFIG_GROUP, DISABLED_GROUPS_KEY);
			}
			else
			{
				configManager.setConfiguration(OWN_CONFIG_GROUP, DISABLED_GROUPS_KEY, String.join(",", hexes));
			}
		}
	}

	private void openItemSearch(Color colour)
	{
		List<SearchItem> cached = itemIndex;
		if (cached != null)
		{
			showItemSearchDialog(colour, cached);
			return;
		}

		panel.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
		clientThread.invoke(() ->
		{
			ensureItemIndexBuilt();
			List<SearchItem> items = itemIndex == null ? Collections.emptyList() : itemIndex;

			SwingUtilities.invokeLater(() ->
			{
				panel.setCursor(Cursor.getDefaultCursor());
				showItemSearchDialog(colour, items);
			});
		});
	}

	private void showItemSearchDialog(Color colour, List<SearchItem> items)
	{
		Window owner = SwingUtilities.windowForComponent(panel);
		ItemSearchDialog dialog = new ItemSearchDialog(owner, items, selected ->
			configManager.setConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + selected.getId(), colour));
		dialog.setVisible(true);
	}

	/**
	 * Scans every item id known to the client - tradeable or not - collapsing noted/placeholder
	 * variants to their canonical item via {@link ItemManager#canonicalize}, the same approach
	 * RuneLite's own item search chatbox uses. Must run on the client thread since item
	 * compositions are read from the game's item cache.
	 */
	private List<SearchItem> buildItemIndex()
	{
		Map<Integer, String> byId = new LinkedHashMap<>();

		int count = client.getItemCount();
		for (int id = 0; id < count; id++)
		{
			int canonicalId = itemManager.canonicalize(id);
			if (byId.containsKey(canonicalId))
			{
				continue;
			}

			String name;
			try
			{
				name = itemManager.getItemComposition(canonicalId).getName();
			}
			catch (Exception e)
			{
				// Skip just this one id rather than letting the whole scan fail (and itemIndex stay
				// null, silently breaking every wildcard pattern) - see hydrate() for the same
				// item-cache-not-ready-yet situation this guards against.
				continue;
			}

			if (name == null || name.equalsIgnoreCase("null"))
			{
				continue;
			}

			byId.put(canonicalId, name);
		}

		List<SearchItem> items = new ArrayList<>(byId.size());
		byId.forEach((id, name) -> items.add(new SearchItem(id, name)));
		items.sort(Comparator.comparing(SearchItem::getName, String.CASE_INSENSITIVE_ORDER));
		return items;
	}

	private void ensureItemIndexBuilt()
	{
		if (itemIndex == null)
		{
			List<SearchItem> built = buildItemIndex();
			if (!built.isEmpty())
			{
				itemIndex = built;
			}
			// Otherwise the item cache probably wasn't ready yet (e.g. right after a game update,
			// on the very first refresh of a session) and the scan skipped everything - leave
			// itemIndex null so the next call retries, rather than getting stuck permanently empty.
		}
	}

	/**
	 * Every item id currently matching {@code colour}'s stored wildcard patterns. Cheap: just a
	 * name-matching scan of the already-cached item index, no per-item config reads or icon fetches.
	 */
	private Set<Integer> currentPatternMatchIds(Color colour)
	{
		List<String> patterns = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + colourHex(colour)));
		if (patterns.isEmpty())
		{
			return Collections.emptySet();
		}

		ensureItemIndexBuilt();
		List<SearchItem> index = itemIndex;
		if (index == null)
		{
			return Collections.emptySet();
		}

		Set<Integer> ids = new HashSet<>();
		for (SearchItem candidate : index)
		{
			if (matchesAny(candidate.getName(), patterns))
			{
				ids.add(candidate.getId());
			}
		}
		return ids;
	}

	private List<ColourGroup> buildGroups()
	{
		Map<Color, List<Integer>> enabledIds = collectItemIds(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX);
		Map<Color, List<Integer>> disabledIds = collectItemIds(OWN_CONFIG_GROUP, DISABLED_KEY_PREFIX);
		Map<Color, List<String>> patternsByColour = collectPatterns();
		Set<String> disabledGroupHexes = readDisabledGroupHexes();

		Map<Color, Set<Integer>> patternMatchIds = resolvePatternMatches(patternsByColour, disabledGroupHexes, enabledIds);

		if (!patternsByColour.isEmpty())
		{
			ensureItemIndexBuilt();
		}
		List<SearchItem> index = itemIndex;

		Map<Color, Boolean> enabledByColour = new TreeMap<>(GroundItemColourGroupsPlugin::compareByHue);
		enabledIds.keySet().forEach(colour -> enabledByColour.put(colour, true));
		disabledIds.keySet().forEach(colour -> enabledByColour.putIfAbsent(colour, false));
		patternsByColour.keySet().forEach(colour ->
			enabledByColour.putIfAbsent(colour, !disabledGroupHexes.contains(colourHex(colour))));

		List<ColourGroup> groups = new ArrayList<>();
		for (Map.Entry<Color, Boolean> entry : enabledByColour.entrySet())
		{
			Color colour = entry.getKey();
			Set<Integer> patternIds = patternMatchIds.getOrDefault(colour, Collections.emptySet());

			// Individually-managed rows only: an id that's a pattern match is represented by its
			// pattern's single summary row instead (below), never hydrated with a name/icon lookup
			// or given its own row - the whole point of a wildcard pattern is to avoid that cost.
			List<ColouredGroundItem> items = new ArrayList<>();
			for (int id : enabledIds.getOrDefault(colour, Collections.emptyList()))
			{
				if (!patternIds.contains(id))
				{
					items.add(hydrate(id));
				}
			}
			for (int id : disabledIds.getOrDefault(colour, Collections.emptyList()))
			{
				items.add(hydrate(id));
			}
			items.sort(Comparator.comparing(ColouredGroundItem::getName, String.CASE_INSENSITIVE_ORDER));

			List<PatternMatch> patternMatches = new ArrayList<>();
			for (String pattern : patternsByColour.getOrDefault(colour, Collections.emptyList()))
			{
				patternMatches.add(index == null ? new PatternMatch(pattern, 0, null) : buildPatternMatch(pattern, index));
			}

			groups.add(new ColourGroup(colour, groupDisplayName(colour), entry.getValue(), items, patternMatches));
		}

		return groups;
	}

	private ColouredGroundItem hydrate(int itemId)
	{
		ColouredGroundItem cached = hydrationCache.get(itemId);
		if (cached != null)
		{
			return cached;
		}

		String name;
		try
		{
			name = itemManager.getItemComposition(itemId).getName();
		}
		catch (Exception e)
		{
			name = null;
		}

		AsyncBufferedImage image = itemManager.getImage(itemId);

		if (name == null || name.isEmpty() || name.equalsIgnoreCase("null"))
		{
			// The item cache may not be ready yet - e.g. right after a game update, on the very
			// first refresh of a session. Don't cache this fallback: a real name should resolve on
			// a later refresh once it is ready, and unlike a real result this must be free to retry.
			return new ColouredGroundItem(itemId, "Item " + itemId, image);
		}

		ColouredGroundItem hydrated = new ColouredGroundItem(itemId, name, image);
		hydrationCache.put(itemId, hydrated);
		return hydrated;
	}

	/**
	 * Counts every item currently matching {@code pattern} and, for display, hydrates just the
	 * first one found (reusing the hydration cache, so this costs a real itemManager lookup only
	 * once per pattern ever seen) to give the pattern's row a real icon instead of a blank
	 * placeholder - without paying that cost for every match, only one per pattern.
	 */
	private PatternMatch buildPatternMatch(String pattern, List<SearchItem> index)
	{
		Pattern compiled = compileWildcard(pattern);
		int count = 0;
		Integer firstMatchId = null;
		for (SearchItem candidate : index)
		{
			if (!compiled.matcher(candidate.getName()).matches())
			{
				continue;
			}

			if (firstMatchId == null)
			{
				firstMatchId = candidate.getId();
			}
			count++;
		}

		AsyncBufferedImage sampleImage = firstMatchId == null ? null : hydrate(firstMatchId).getImage();
		return new PatternMatch(pattern, count, sampleImage);
	}

	/**
	 * Reads every {@code keyPrefix + itemId} entry under {@code configGroup}, resolving each item's
	 * colour and grouping the ids by it. Used for both the live GroundItemsConfig entries and this
	 * plugin's own store of bulk-disabled items. Deliberately cheap - no name/icon lookups - since
	 * most of these ids may turn out to be pattern matches that are never displayed individually.
	 */
	private Map<Color, List<Integer>> collectItemIds(String configGroup, String keyPrefix)
	{
		String prefix = configGroup + "." + keyPrefix;
		List<String> keys = configManager.getConfigurationKeys(prefix);

		Map<Color, List<Integer>> grouped = new LinkedHashMap<>();

		for (String wholeKey : keys)
		{
			int itemId = parseItemId(wholeKey, prefix);
			if (itemId < 0)
			{
				continue;
			}

			Color colour = configManager.getConfiguration(configGroup, keyPrefix + itemId, Color.class);
			if (colour == null)
			{
				continue;
			}

			grouped.computeIfAbsent(colour, c -> new ArrayList<>()).add(itemId);
		}

		return grouped;
	}

	/**
	 * Reads every colour's stored wildcard pattern list (OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX +
	 * colour hex, a comma-separated string), keyed by the colour it applies to.
	 */
	private Map<Color, List<String>> collectPatterns()
	{
		String prefix = OWN_CONFIG_GROUP + "." + PATTERN_KEY_PREFIX;
		List<String> keys = configManager.getConfigurationKeys(prefix);

		Map<Color, List<String>> patternsByColour = new LinkedHashMap<>();
		for (String wholeKey : keys)
		{
			String hex = wholeKey.substring(prefix.length());
			Color colour = parseColourHex(hex);
			if (colour == null)
			{
				continue;
			}

			List<String> patterns = splitPatterns(configManager.getConfiguration(OWN_CONFIG_GROUP, PATTERN_KEY_PREFIX + hex));
			if (!patterns.isEmpty())
			{
				patternsByColour.put(colour, patterns);
			}
		}

		return patternsByColour;
	}

	/**
	 * For every colour with active (non-disabled) wildcard patterns, matches those patterns against
	 * the full item catalogue (already cached in {@code itemIndex}, so this is just name-matching -
	 * no per-item itemManager calls) and returns the matching item ids per colour. Any match that
	 * isn't already highlighted (with any colour) gets its highlight_ entry written here so the game
	 * actually shows it. Never touches an item that's already coloured (by hand or by a different
	 * pattern), so narrowing or editing a pattern never strips an existing colour.
	 */
	private Map<Color, Set<Integer>> resolvePatternMatches(Map<Color, List<String>> patternsByColour,
		Set<String> disabledGroupHexes, Map<Color, List<Integer>> enabledIds)
	{
		Map<Color, Set<Integer>> matchIdsByColour = new LinkedHashMap<>();
		if (patternsByColour.isEmpty())
		{
			return matchIdsByColour;
		}

		ensureItemIndexBuilt();
		List<SearchItem> index = itemIndex;
		if (index == null)
		{
			return matchIdsByColour;
		}

		for (Map.Entry<Color, List<String>> entry : patternsByColour.entrySet())
		{
			Color colour = entry.getKey();
			if (disabledGroupHexes.contains(colourHex(colour)))
			{
				// Group is bulk-disabled - leave pattern matching paused until it's re-enabled.
				continue;
			}

			List<String> patterns = entry.getValue();
			Set<Integer> alreadyHighlighted = new HashSet<>(enabledIds.getOrDefault(colour, Collections.emptyList()));

			Set<Integer> matchIds = new HashSet<>();
			List<Integer> newMatches = new ArrayList<>();
			for (SearchItem candidate : index)
			{
				if (!matchesAny(candidate.getName(), patterns))
				{
					continue;
				}

				int id = candidate.getId();
				matchIds.add(id);
				if (!alreadyHighlighted.contains(id)
					&& configManager.getConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + id, Color.class) == null)
				{
					newMatches.add(id);
				}
			}

			if (!newMatches.isEmpty())
			{
				suppressConfigEvents = true;
				try
				{
					for (int id : newMatches)
					{
						configManager.setConfiguration(GroundItemsConfig.GROUP, HIGHLIGHT_KEY_PREFIX + id, colour);
					}
				}
				finally
				{
					suppressConfigEvents = false;
				}
			}

			matchIdsByColour.put(colour, matchIds);
		}

		return matchIdsByColour;
	}

	private boolean matchesAny(String name, List<String> patterns)
	{
		for (String pattern : patterns)
		{
			if (compileWildcard(pattern).matcher(name).matches())
			{
				return true;
			}
		}
		return false;
	}

	private Pattern compileWildcard(String wildcard)
	{
		return wildcardPatternCache.computeIfAbsent(wildcard, GroundItemColourGroupsPlugin::translateWildcardToPattern);
	}

	/**
	 * Translates a simple {@code *}-wildcard string into an equivalent case-insensitive regex, the
	 * same semantics as {@link net.runelite.client.util.WildcardMatcher}: every run of literal
	 * characters is escaped verbatim (so regex metacharacters in a pattern like "(t)" are matched
	 * literally, not interpreted), and every run of one or more {@code *} becomes {@code .*}.
	 */
	private static Pattern translateWildcardToPattern(String wildcard)
	{
		StringBuilder regex = new StringBuilder();
		int length = wildcard.length();
		int i = 0;
		while (i < length)
		{
			int star = wildcard.indexOf('*', i);
			if (star < 0)
			{
				regex.append(Pattern.quote(wildcard.substring(i)));
				break;
			}

			if (star > i)
			{
				regex.append(Pattern.quote(wildcard.substring(i, star)));
			}
			regex.append(".*");

			i = star + 1;
			while (i < length && wildcard.charAt(i) == '*')
			{
				i++;
			}
		}
		return Pattern.compile(regex.toString(), Pattern.CASE_INSENSITIVE);
	}

	private static List<String> splitPatterns(String csv)
	{
		List<String> patterns = new ArrayList<>();
		if (csv != null)
		{
			for (String part : csv.split(","))
			{
				String trimmed = part.trim();
				if (!trimmed.isEmpty())
				{
					patterns.add(trimmed);
				}
			}
		}
		return patterns;
	}

	private static String colourHex(Color colour)
	{
		return String.format("%08x", colour.getRGB());
	}

	private static Color parseColourHex(String hex)
	{
		try
		{
			return new Color(Integer.parseUnsignedInt(hex, 16), true);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static int parseItemId(String wholeKey, String prefix)
	{
		try
		{
			return Integer.parseInt(wholeKey.substring(prefix.length()));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static int compareByHue(Color a, Color b)
	{
		float[] hsbA = Color.RGBtoHSB(a.getRed(), a.getGreen(), a.getBlue(), null);
		float[] hsbB = Color.RGBtoHSB(b.getRed(), b.getGreen(), b.getBlue(), null);

		int hue = Float.compare(hsbA[0], hsbB[0]);
		if (hue != 0)
		{
			return hue;
		}

		int saturation = Float.compare(hsbB[1], hsbA[1]);
		if (saturation != 0)
		{
			return saturation;
		}

		int brightness = Float.compare(hsbB[2], hsbA[2]);
		if (brightness != 0)
		{
			return brightness;
		}

		return Integer.compare(a.getRGB(), b.getRGB());
	}

	private static BufferedImage createIcon()
	{
		int size = 16;
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int half = size / 2;
		g.setColor(new Color(0xE0, 0x4B, 0x4B));
		g.fillRect(0, 0, half, half);
		g.setColor(new Color(0x4B, 0xAE, 0x4B));
		g.fillRect(half, 0, half, half);
		g.setColor(new Color(0x4B, 0x7B, 0xE0));
		g.fillRect(0, half, half, half);
		g.setColor(new Color(0xE0, 0xC9, 0x4B));
		g.fillRect(half, half, half, half);

		g.dispose();
		return image;
	}
}

